```python
def tenumerate(iterable, start=0, total=None, tqdm_class=tqdm_auto, **tqdm_kwargs):
    """
    Equivalent of `numpy.ndenumerate` or builtin `enumerate`.

    Parameters
    ----------
    tqdm_class  : [default: tqdm.auto.tqdm].
    """
    try:
        import numpy as np
    except ImportError:
        pass
    else:
        if isinstance(iterable, np.ndarray):
            if total is None:
                total = iterable.size
            return tqdm_class(np.ndenumerate(iterable), total=total, **tqdm_kwargs)

    if total is None:
        try:
            total = len(iterable)
        except TypeError:
            # Handle the case where the length of the iterable is unknown
            pass

    # Use tqdm class without start to correctly handle the starting index
    tqdm_iter = tqdm_class(iterable, total=total, **tqdm_kwargs)

    # Manually add the start index to the enumerate call
    return enumerate(tqdm_iter, start=start)
```
